        static void Need(bool value,string message){if(!value)throw new Exception(message);}
        static int N(string value){return int.Parse(value,System.Globalization.CultureInfo.InvariantCulture);}
        static uint U(string value){return uint.Parse(value,System.Globalization.CultureInfo.InvariantCulture);}
        static string Hash(byte[] bytes){using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(bytes)).Replace("-","");}
        static string Digest(PracticeGeneratedReinforcements world){using(var stream=new MemoryStream())using(var writer=new BinaryWriter(stream)){world.WriteOriginalSnapshot(writer);writer.Flush();return Hash(stream.ToArray());}}
        static bool Reject(Action action){try{action();return false;}catch(ArgumentException){return true;}catch(InvalidDataException){return true;}catch(NotSupportedException){return true;}catch(InvalidOperationException){return true;}}
        static PracticeReinforcementPhaseState To(PracticeReinforcementPhaseState state,int frame){while(state.Frames<frame)state=state.AdvanceFrame().State;return state;}
        internal static void Run(Action<string,Action> check,string assets)
        {
            string programs=Path.Combine(Path.GetDirectoryName(assets),"Programs");
            check("Phase-gated waves match1728original before/after cores and all phase/pause/caller/contact observations",delegate{
                var tables=PracticeReinforcementTables.Load(programs);byte[] map=File.ReadAllBytes(Path.Combine(assets,"Graphics","BSSB202.SCN"));Need(Profiles.Length==18&&Frames.Length==1728,"Original phase corpus extents");int row=0,drivers=0,polls=0,paused=0,creations=0,contactOnes=0;
                for(int id=0;id<Profiles.Length;id++)
                {
                    string[] p=Profiles[id].Split(',');Need(p.Length==7&&N(p[0])==id,"Original phase history metadata");uint seed=U(p[1]);var raw=new byte[128];int sourceCase=seed==731?4:16;for(int n=0;n<raw.Length;n++)raw[n]=(byte)(0x5b^sourceCase^n);var state=PracticeReinforcementPhaseState.CreateFixture(tables,programs,map,seed,U(p[2]),N(p[3]),raw);Need(state.FirstDeadline==N(p[4])&&state.LastDeadline==N(p[5])&&Digest(state.World)==p[6],"Original after-late starting core/idle recipe");
                    for(int frame=0;frame<96;frame++)
                    {
                        string[] f=Frames[row++].Split(',');Need(f.Length==13&&N(f[0])==id&&N(f[1])==frame,"Original frame order");var update=state.AdvanceFrame();Need(update.GameClock==U(f[2])&&update.PauseWord==N(f[3])&&state.PhaseCounter==U(f[4])&&update.State.PhaseCounter==U(f[5])&&(update.DriverCalled?1:0)==N(f[6])&&update.CallerScratch==U(f[7])&&N(f[8])==0,"Original phase/pause/caller/UI observations");Need(update.RefreshContactBytes.Count==N(f[9]),"Original source refresh count");string contacts=string.Join(":",System.Linq.Enumerable.Select(update.RefreshContactBytes,b=>b.ToString(System.Globalization.CultureInfo.InvariantCulture)));Need(contacts==f[10]&&Digest(update.PreparedWorld)==f[11]&&Digest(update.State.World)==f[12],"Original complete before/after cores and refresh ordering");if(update.DriverCalled)drivers++;if(update.ConsumerPolled)polls++;if(update.PauseWord!=0)paused++;creations+=update.RefreshContactBytes.Count;foreach(byte b in update.RefreshContactBytes)if(b==1)contactOnes++;state=update.State;
                    }
                }
                Need(row==1728&&drivers==1692&&polls==50&&paused==36&&creations==144&&contactOnes==20,"Original controlled timeline totals");
            });
            check("Wave driver delays due construction until an admitted32phase poll",delegate{
                var state=PracticeReinforcementPhaseState.Create(PracticeReinforcementTables.Load(programs),programs,File.ReadAllBytes(Path.Combine(assets,"Graphics","BSSB202.SCN")),731,0,0);var initial=state;state=To(state,31);Need(state.ConsumerPolls==0&&state.World.CreatedFleetCount==0,"Due clock alone does not poll offphase");var first=state.AdvanceFrame();Need(first.State.Frames==32&&first.State.PhaseCounter==32&&first.ConsumerPolled&&first.State.World.CreatedFleetCount==1,"Source first aligned due poll");state=To(first.State,64);Need(state.World.CreatedFleetCount==8&&state.World.CreatedUnitCount==40&&state.ConsumerPolls==2&&initial.World.CreatedFleetCount==0,"All eight source events at next admitted poll/immutable past");
            });
            check("Nonzero pause holds phase32 and suppresses the whole driver before delayed resumption",delegate{
                var state=PracticeReinforcementPhaseState.Create(PracticeReinforcementTables.Load(programs),programs,File.ReadAllBytes(Path.Combine(assets,"Graphics","BSSB202.SCN")),731,0,2);state=To(state,32);Need(state.World.CreatedFleetCount==1,"Source first wave before hold");for(int n=0;n<3;n++){var held=state.AdvanceFrame();Need(held.PauseWord==short.MinValue&&!held.DriverCalled&&!held.ConsumerPolled&&held.State.PhaseCounter==32&&held.State.World.CreatedFleetCount==1&&held.CallerScratch==PracticeReinforcementPhaseState.SkippedCallerSentinel,"Negative pause gates body and phase");state=held.State;}state=To(state,66);Need(state.World.CreatedFleetCount==1,"No early remaining burst");var resumed=state.AdvanceFrame();Need(resumed.State.Frames==67&&resumed.ConsumerPolled&&resumed.State.World.LastCreated.Count==7&&resumed.State.World.CreatedFleetCount==8,"Remaining events on delayed phase64");
            });
            check("Initial phase31/MAX can poll at exact equality and preserve unsigned counter wrap",delegate{
                foreach(uint phase in new[]{31u,uint.MaxValue}){var state=PracticeReinforcementPhaseState.Create(PracticeReinforcementTables.Load(programs),programs,File.ReadAllBytes(Path.Combine(assets,"Graphics","BSSB202.SCN")),731,phase,0);var first=state.AdvanceFrame();Need(first.ConsumerPolled&&first.State.World.CreatedFleetCount==0&&first.State.PhaseCounter==(phase==31?32u:0u),"Aligned exact equality and source wrap");state=To(first.State,33);Need(state.World.CreatedFleetCount==8&&state.ConsumerPolls==2,"Next aligned poll receives overdue group-slot burst");}
            });
            check("Wave refresh observes contact before neutral visibility in the copied idle profile",delegate{
                var state=PracticeReinforcementPhaseState.Create(PracticeReinforcementTables.Load(programs),programs,File.ReadAllBytes(Path.Combine(assets,"Graphics","BSSB202.SCN")),731,0,0);Need(state.ContactByte249==1,"Explicit inactive contact sentinel");var update=To(state,31).AdvanceFrame();Need(update.RefreshContactBytes.Count==1&&update.RefreshContactBytes[0]==1&&update.State.ContactByte249==0,"Consumer refresh precedes neutral clear");byte[] runtime=update.State.World.CopyRuntimePool();for(int fleet=0;fleet<250;fleet++)Need(BitConverter.ToInt32(runtime,fleet*312+204)==0x4b47a0+fleet*492&&BitConverter.ToInt32(runtime,fleet*312+304)==0,"Copied idle-reference recipe retained");foreach(byte b in state.World.CopyTerrainPool())Need(b==0,"Explicit zero-terrain diagnostic profile");
            });
            check("Phase study reset preserves the applied idle fixture and rejects unsupported inputs/frame97",delegate{
                var tables=PracticeReinforcementTables.Load(programs);byte[] map=File.ReadAllBytes(Path.Combine(assets,"Graphics","BSSB202.SCN"));var initial=PracticeReinforcementPhaseState.Create(tables,programs,map,731,0,0);string before=Digest(initial.World);var end=To(initial,96);Need(!end.CanAdvance&&Reject(delegate{end.AdvanceFrame();})&&Digest(end.ResetCopy().World)==before&&end.ResetCopy().Frames==0,"Finite modern guard/reset without partial publication");Need(Reject(delegate{PracticeReinforcementPhaseState.Create(tables,programs,map,731,1,0);})&&Reject(delegate{PracticeReinforcementPhaseState.Create(tables,programs,map,731,0,3);})&&Reject(delegate{PracticeReinforcementPhaseState.Create(tables,programs,map,1,0,0);})&&Reject(delegate{PracticeReinforcementPhaseState.CreateFixture(tables,programs,map,731,0,0,new byte[127]);}),"Explicit compared phase/seed/profile/input bounds");var copy=initial.World.CopyRuntimePool();copy[204]^=1;Need(Digest(initial.World)==before,"Inspection arrays cannot change source links");
            });
